export const TAU=Math.PI*2;
export const clamp=(v,min,max,fallback=min)=>Math.min(max,Math.max(min,Number.isFinite(Number(v))?Number(v):fallback));
// dB-Wert eines Teiltons relativ zum stärksten (halbe Amplitude −6 dB, ein Zehntel −20 dB); null bei Stille.
export const relativeDb=(a,max)=>a>0&&max>0?Math.round(20*Math.log10(a/max)):null;
export function makePartials(count=9,preset='sine',fundamental=220){return Array.from({length:count},(_,i)=>{const n=i+1;let a=0,p=0;if(preset==='sine')a=i===0?1:0;if(preset==='saw')a=1/n;if(preset==='square')a=n%2?1/n:0;if(preset==='triangle'){a=n%2?1/(n*n):0;p=n%4===3?180:0;}return {a,f:fundamental*n,p,mute:false,solo:false};});}
export function activePartials(s,sampleRate=48000){const solo=s.partials.some(p=>p.solo);return s.partials.map((p,i)=>({a:p.mute||(solo&&!p.solo)?0:p.a,f:s.harmonic?s.fundamental*(i+1):p.f,p:p.p*TAU/360})).filter(p=>p.f>0&&p.f<sampleRate/2);}
export function normalization(partials){return 1/Math.max(1,partials.reduce((a,p)=>a+Math.abs(p.a),0));}
export function generateSamples(s,size,sampleRate=48000,offset=0){const parts=activePartials(s,sampleRate),norm=normalization(parts);const out=new Float32Array(size);for(let i=0;i<size;i++){let sum=0;for(const p of parts)if(p.a)sum+=p.a*Math.sin(TAU*p.f*(i/sampleRate+offset)+p.p);out[i]=sum*norm;}return out;}
// FFT matches Web Audio's Blackman window and 1/N magnitude convention.
export function spectrum(samples){const n=samples.length;if(n<2||(n&(n-1)))throw new Error('FFT size must be a power of two');const re=new Float64Array(n),im=new Float64Array(n);for(let i=0;i<n;i++)re[i]=samples[i]*(.42-.5*Math.cos(TAU*i/n)+.08*Math.cos(2*TAU*i/n));for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]];}for(let len=2;len<=n;len<<=1){const angle=-TAU/len,wr=Math.cos(angle),wi=Math.sin(angle);for(let i=0;i<n;i+=len){let ur=1,ui=0;for(let j=0;j<len/2;j++){const k=i+j,l=k+len/2,tr=re[l]*ur-im[l]*ui,ti=re[l]*ui+im[l]*ur;re[l]=re[k]-tr;im[l]=im[k]-ti;re[k]+=tr;im[k]+=ti;const next=ur*wr-ui*wi;ui=ur*wi+ui*wr;ur=next;}}}return Float32Array.from({length:n/2},(_,i)=>20*Math.log10(Math.max(1e-8,Math.hypot(re[i],im[i])/n)));}
export function validateSound(input){if(!input||!Array.isArray(input.partials)||input.partials.length<1||input.partials.length>32)throw new Error('Invalid sound');const fundamental=clamp(input.fundamental,20,20000,220);return{fundamental,harmonic:input.harmonic!==false,preset:['sine','triangle','square','saw','custom'].includes(input.preset)?input.preset:'custom',partials:input.partials.map((p,i)=>({a:clamp(p.a,0,1),f:clamp(p.f??fundamental*(i+1),1,22000),p:clamp(p.p,-180,180,0),mute:!!p.mute,solo:!!p.solo}))};}
export function wavBuffer(samples,sampleRate=48000){const buffer=new ArrayBuffer(44+samples.length*2),v=new DataView(buffer);function str(at,s){for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i));}str(0,'RIFF');v.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++)v.setInt16(44+i*2,clamp(samples[i],-1,1)*(samples[i]<0?32768:32767),true);return buffer;}
